# model: s.find("xn--")==0 ? s.substr(4) : s
sub model { my $s = shift; return (index($s,"xn--") == 0) ? substr($s,4) : $s; }

my $n = 0; my $bad = 0; my $modelbad = 0; my $f2f4 = 0;
my @inputs;
# inputs with no spaces/newlines so field split is unambiguous
push @inputs, "", "a", "xn--", "xn---", "xn--a", "XN--a", "xn-", "xnxn--a",
  "xn--xn--", "xn--xn--a", ".", "xn--.", ".xn--", "xn--..", "..xn--a",
  "xn--A", "xn--Z", "xn--0", "xn--_", "xn--\xff", "\xffxn--a";
for my $i (1..255) { next if $i==32 || $i==10; push @inputs, "xn--".chr($i), chr($i)."xn--a", "xn-".chr($i)."-a"; }
for my $L (0..8, 60..66, 250..258, 1000, 4096) { push @inputs, "a"x$L, "xn--"."a"x$L; }
push @inputs, "xn--".("b"x200000), ("c"x300000)."xn--d", "xn--".("z"x1000000);

for my $s (@inputs) {
